,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Use report mode with one row per plan (2 to 4 plans read best). Map Features to a column that joins the features with |, for example Unlimited orders|Priority support. Map Highlight to a column returning Y for the recommended plan. The call to action renders as a native Universal Theme button (hot for the highlighted plan).'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
